WITH valid AS (SELECT id, customer_id, account_type, balance, opened_date, status, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_date_label, CONCAT_WS('-', status, account_type) AS status_account_type_key, COALESCE(status, 'N/A') AS resolved_status FROM accounts WHERE opened_date >= DATE '2024-01-19' AND balance BETWEEN 18000 AND 20000), latest_match AS (SELECT s.*, top1.txn_type FROM valid s LEFT JOIN LATERAL (SELECT c.txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.merchant IN ('7-Eleven', 'Starbucks', 'Lazada'))) SELECT id, balance, status, status_account_type_key, resolved_status, txn_type FROM not_flagged ORDER BY id DESC NULLS FIRST;
